//! Schemas of the native image tools: `image_trace`, `image_segment`, `image_inpaint`.
use super::ToolSchema;

pub(crate) const IMAGE_TOOLS: &[ToolSchema] = &[
    ToolSchema {
        name: "image_trace",
        description: "Trace a PNG into flat-colour vector paths with no external tools: k-means colour quantisation (seeded, deterministic), exact contour following with holes, Bezier fitting, largest colour first so layers stack without gaps. path is a PNG (not interlaced, at most 16 megapixels and 64 MiB) in a granted directory; JPEG is not supported, convert it first. k 1-64 colours (default 16); minArea drops outer contours smaller than that many pixels (default pixels/12000 clamped to 30-400, so 197 for 1536x1536); tolerance 0.25-8 px is the allowed distance between curve and pixel outline (default 1.5); region [x0,y0,x1,y1] traces only that pixel rectangle (coordinates stay in image pixels); seed changes the quantiser start. With groupId (an existing <g> id, or root) the layers are added as one <path> per colour under that group, ids <idPrefix>-0.. (default trace), in ONE undoable edit, within the 4096-element and 4 MiB document limits; without groupId nothing is edited and the paths are returned. Returns {width,height,colors,layers,bytes,elementIds|paths:[{fill,d}]}. A 1536 px scene at k=24 takes about 1-3 s. Example: {\"path\":\"/Users/me/art/village.png\",\"k\":24,\"groupId\":\"root\",\"idPrefix\":\"village\"}.",
        properties: "{\"documentId\":{\"type\":\"string\"},\"path\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":1023},\"k\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":64},\"minArea\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":1000000},\"tolerance\":{\"type\":\"number\",\"minimum\":0.25,\"maximum\":8},\"region\":{\"type\":\"array\",\"items\":{\"type\":\"integer\",\"minimum\":0},\"minItems\":4,\"maxItems\":4},\"seed\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":4294967295},\"groupId\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":120},\"idPrefix\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":40}}",
        required: "documentId,path",
        fields: "documentId:string;path:string;k:integer;minArea:integer;tolerance:number;region:array;seed:integer;groupId:string;idPrefix:string",
    },
    ToolSchema {
        name: "image_segment",
        description: "Cut a part out of a PNG by colour: a small colour model is learned around the seed pixels, grown by flood fill and refined a few rounds (a GrabCut-style alternative, no external tools). seeds: 1-64 [x,y] pixels inside the part; include: up to 16 polygons ([[x,y],...] 3-512 points, image pixels) that confine the mask to their union; exclude: polygons that are never part of the mask; tolerance 0-441 is the extra RGB distance accepted (default 36); fillHoles (default true) fills pockets that do not touch the border. Returns {width,height,area,bbox:[x0,y0,x1,y1]}. outMask writes the mask as an opaque black/white PNG (white = part) in a granted directory, refusing to overwrite; trace:true also returns the mask outline as path data d (clockwise outer, holes reversed). Example: {\"path\":\"/Users/me/art/kira.png\",\"seeds\":[[420,310]],\"exclude\":[[[0,0],[200,0],[200,200]]],\"outMask\":\"/Users/me/art/kira_mask.png\",\"trace\":true}.",
        properties: "{\"documentId\":{\"type\":\"string\"},\"path\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":1023},\"seeds\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":64,\"items\":{\"type\":\"array\",\"items\":{\"type\":\"integer\",\"minimum\":0},\"minItems\":2,\"maxItems\":2}},\"include\":{\"type\":\"array\",\"maxItems\":16,\"items\":{\"type\":\"array\"}},\"exclude\":{\"type\":\"array\",\"maxItems\":16,\"items\":{\"type\":\"array\"}},\"tolerance\":{\"type\":\"number\",\"minimum\":0,\"maximum\":441},\"fillHoles\":{\"type\":\"boolean\"},\"outMask\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":1023},\"trace\":{\"type\":\"boolean\"}}",
        required: "documentId,path,seeds",
        fields: "documentId:string;path:string;seeds:array;include:array;exclude:array;tolerance:number;fillHoles:boolean;outMask:string;trace:boolean",
    },
    ToolSchema {
        name: "image_inpaint",
        description: "Fill masked pixels of a PNG from their surroundings (fast-marching, inverse-distance average) and write the result as a PNG underlay, for example the background behind a character that was cut out. Give the mask as maskPath (PNG of the same size: white, alpha >= 128 = fill; as written by image_segment outMask) or polygon ([[x,y],...] 3-512 points in image pixels). outPath is a new .png file in a granted directory (an existing file is never overwritten). The mask must leave some pixels unmasked. Returns {outPath,width,height,filled,bytes}. Example: {\"path\":\"/Users/me/art/village.png\",\"maskPath\":\"/Users/me/art/kira_mask.png\",\"outPath\":\"/Users/me/art/village_clean.png\"}.",
        properties: "{\"documentId\":{\"type\":\"string\"},\"path\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":1023},\"maskPath\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":1023},\"polygon\":{\"type\":\"array\",\"minItems\":3,\"maxItems\":512,\"items\":{\"type\":\"array\"}},\"outPath\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":1023}}",
        required: "documentId,path,outPath",
        fields: "documentId:string;path:string;maskPath:string;polygon:array;outPath:string",
    },
];
